# -*- coding: utf-8 -*-
from common import md, esc, cq, wq, verse_card
def eras():
    E=[("🌳","创造","创1–2","神造天地与人；人受托治理全地","徒14:15；徒17:24-26"),
       ("🍎","堕落","创3","罪与死进入世界；女人后裔的应许","徒17:30-31（审判）"),
       ("🗼","巴别","创11","骄傲的统一 → 变乱口音、分散列国","徒2（五旬节反转）"),
       ("⭐","亚伯拉罕","创12–22","万族因你得福；割礼为记号","徒3:25；徒7:2-8；徒13:26"),
       ("⛰️","摩西 / 西奈","出19–24","律法、会幕、先知像摩西","徒3:22；徒7:17-44；徒15"),
       ("👑","大卫","撒下7","永远的王位；帐幕将重建","徒2:30-36；徒13:22-37；徒15:16"),
       ("⛓️","被掳与先知","赛49；珥2；结36","圣灵浇灌、外邦人之光、新心","徒2:17-21；徒13:47"),
       ("✝️","基督","路加福音","受死、复活、升天","徒1:1-11；每篇讲道的中心"),
       ("🔥","五旬节与教会","使徒行传","升天之主浇灌圣灵；道从耶路撒冷到罗马","全书"),
       ("🌅","再来与新创造","启21–22","万物复兴、审判、复活","徒1:11；徒3:21；徒17:31")]
    s='<div class="eras">'
    for i,(ic,t,r,d,ep) in enumerate(E):
        s+=f'<div class="era reveal" style="--i:{i}"><span class="eic">{ic}</span><b>{t}</b><small>{r}</small><p>{d}</p><p class="epl">🔥 {ep}</p></div>'
    return s+'</div>'
def twoage():
    return '''<figure class="twoage glass reveal"><svg viewBox="0 0 1000 300" role="img" aria-label="两个世代图：末后的日子">
<defs><linearGradient id="ta1" x1="0" x2="1"><stop offset="0" stop-color="#7c8796"/><stop offset="1" stop-color="#e0573e"/></linearGradient><linearGradient id="ta2" x1="0" x2="1"><stop offset="0" stop-color="#f5b942"/><stop offset="1" stop-color="#3fd39a"/></linearGradient></defs>
<line x1="40" y1="200" x2="720" y2="200" stroke="url(#ta1)" stroke-width="10" stroke-linecap="round"/>
<path d="M420,200 Q420,90 520,90 L960,90" fill="none" stroke="url(#ta2)" stroke-width="10" stroke-linecap="round" class="draw"/>
<rect x="420" y="80" width="300" height="130" fill="#f5b942" opacity=".10" rx="14"/>
<circle cx="420" cy="200" r="13" fill="#f5b942"/><circle cx="720" cy="200" r="13" fill="#3fd39a"/>
<text x="60" y="240" font-size="22" fill="currentColor">“今世”：罪、死亡、分散的列国</text>
<text x="600" y="60" font-size="22" fill="currentColor">“来世”：圣灵、复活、新创造</text>
<text x="420" y="270" font-size="20" text-anchor="middle" fill="#f5b942">复活 · 升天 · 五旬节</text>
<text x="720" y="245" font-size="20" text-anchor="middle" fill="#3fd39a">基督再来（徒1:11）</text>
<text x="570" y="160" font-size="22" text-anchor="middle" fill="currentColor" font-weight="700">使徒行传 = “末后的日子”</text>
</svg><figcaption>彼得引约珥说“在末后的日子”（徒2:17）：五旬节表明来世已经闯入今世。教会活在“已然—未然”之间：圣灵已浇灌，万物复兴尚待基督再来（徒3:21）。图式参 Geerhardus Vos，本站重绘。</figcaption></figure>'''
def covflow():
    C=[("创12:3","亚伯拉罕之约","地上万族因你得福","徒3:25；徒10；徒15"),("出19–24","摩西之约","律法、圣殿、先知像摩西","徒3:22；徒7；徒13:39"),("撒下7","大卫之约","大卫的后裔坐永远的宝座","徒2:30；徒13:34；徒15:16"),
       ("耶31；结36","新约应许","新心、新灵、赦罪","徒2:38；徒5:31；徒13:38"),("珥2:28","圣灵的浇灌","凡有血气的","徒2:17；徒10:45"),("赛49:6","外邦人的光","救恩直到地极","徒1:8；徒13:47；徒26:23")]
    s='<div class="covflow">'
    for i,(r,t,d,ep) in enumerate(C):
        s+=f'<div class="cstep reveal" style="--i:{i}"><small>{r}</small><b>{t}</b><p>{d}</p><span class="cep">🔥 {ep}</span></div>'+('<i class="carr">➜</i>' if i<len(C)-1 else '')
    return s+'</div><p class="note">同一个恩典之约，在不同时代以不同方式施行。使徒行传所记载的，正是这个约从以色列扩展到万国的历史时刻。</p>'
