    Q=[("珥2:28-32","徒2:17-21","圣灵浇灌凡有血气的：末后的日子已到"),("诗16:8-11","徒2:25-28；徒13:35","圣者不见朽坏：复活的预言"),("诗110:1","徒2:34-35","坐在我的右边：升天坐王"),("申18:15","徒3:22；徒7:37","先知像摩西：基督是终极先知"),
       ("创22:18","徒3:25","地上万族因你的后裔得福"),("诗118:22","徒4:11","匠人所弃的石头"),("诗2:1-2,7","徒4:25-26；徒13:33","列国攻击受膏者；你是我的儿子"),("赛53:7-8","徒8:32-33","像羊被牵到宰杀之地：受苦的仆人"),
       ("赛55:3","徒13:34","大卫那圣洁可靠的恩典"),("赛49:6","徒13:47","外邦人的光，施行救恩直到地极"),("摩9:11-12","徒15:16-17","重建大卫倒塌的帐幕，外邦人归主"),("赛6:9-10","徒28:26-27","听是要听见，却不明白：以色列的硬心")]
    b.append('<div class="tbl"><table><thead><tr><th>旧约</th><th>使徒行传</th><th>神学意义</th></tr></thead><tbody>'+"".join(f'<tr><td>{md("{{"+a+"}}") if ":" in a and "," not in a else a}</td><td>{c}</td><td>{d}</td></tr>' for a,c,d in Q)+'</tbody></table></div>')
