    b.append('<div class="types">'+"".join(f'<div class="type reveal"><span class="sh">{a}</span><i>➜</i><span class="re">{c}</span><small>{d}</small></div>' for a,c,d in T)+'</div>')
    b.append(cq(("bc",25,"我们相信，随着基督的降世，礼仪律及其象征已被停用；我们也相信，所有的预表都已实现。因此，它们不应继续为基督徒所用。然而，为了我们的益处，其真理与精髓仍留在耶稣基督里，它们所预表的都在他身上得了成全。")))
    b.append('<h3 id="w2c">👑 升天的基督：全书真正的主角</h3>')
    b.append(f'<div class="two"><div class="card glass"><h4>“开头”所行所教训的</h4><p>{md("路加说前书记载耶稣“开头”一切所行所教训的（{{徒1:1}}）——言下之意：使徒行传记载的是**同一位耶稣继续**所行所教的。祂从天上浇灌圣灵（{{徒2:33}}），把得救的人加给教会（{{徒2:47}}），向司提反显现（{{徒7:56}}），拦阻扫罗（{{徒9:5}}），开导吕底亚的心（{{徒16:14}}），夜里站在保罗旁边（{{徒23:11}}）。")}</p></div><div class="card glass"><h4>先知 · 祭司 · 君王</h4><p>{md("作为**先知**，祂藉使徒的口继续说话；作为**祭司**，祂在父面前代求，已献上一次永远的祭（因此使徒行传没有任何献祭）；作为**君王**，祂“用他的话语和圣灵统管我们”（海德堡要理问答第 31 问），让道从耶路撒冷一路得胜到罗马。")}</p></div></div>')
    b.append(cq(("hc",51)))
    b.append('<h2 id="w3">三、圣约神学：一个恩典之约，扩展到万国</h2>')
    b.append('<h3 id="w3a">🤝 圣约的历史脉络</h3>'+covflow())
